// init.go defines the "init" subcommand.
//
// It scaffolds a default gots.yaml config file in the current directory.
// The generated file includes all available options with sensible defaults
// and commented-out examples for advanced features.
//
// Usage:
//
//	cd myproject && gots init
//
// This will fail if gots.yaml already exists (safety check to avoid overwriting).
package main

import (
	"fmt"
	"os"

	"github.com/spf13/cobra"
)

// initCmd creates a starter gots.yaml with documented defaults.
var initCmd = &cobra.Command{
	Use:   "init",
	Short: "Create a default gots.yaml config file",
	Long:  `Scaffolds a gots.yaml config file in the current directory with sensible defaults.`,
	RunE: func(cmd *cobra.Command, args []string) error {
		// Safety: don't overwrite an existing config
		if _, err := os.Stat("gots.yaml"); err == nil {
			return fmt.Errorf("gots.yaml already exists")
		}

		// The template includes all config keys with defaults and commented examples.
		// Users uncomment what they need rather than looking up docs.
		defaultConfig := `# yaml-language-server: $schema=https://raw.githubusercontent.com/khanakia/gots/main/schema.json

# gots configuration
# Docs: https://github.com/khanakia/gots

default_style: union          # union | enum | const-object
emit_values_array: false
struct_tag: json
pointer_handling: optional    # optional | nullable | both
empty_interface: unknown      # unknown | any
header: "// Code generated by gots. DO NOT EDIT."

type_map:
  time.Time: string
  uuid.UUID: string
  json.RawMessage: unknown

sources:
  - file: "pkg/constants/constants.go"
    output: "./frontend/src/types/constants.ts"
    # style: union
    # include:
    #   - "MessageRole"
    #   - "Feedback*"
    # exclude:
    #   - "InternalThing"

# overrides:
#   MessageRole:
#     style: union
#     values_array: true
#   LockType:
#     style: enum
`

		if err := os.WriteFile("gots.yaml", []byte(defaultConfig), 0644); err != nil {
			return fmt.Errorf("failed to write gots.yaml: %w", err)
		}

		fmt.Println("Created gots.yaml")
		return nil
	},
}
